GEOCODING_FILE_BASENAME = "FULL_GEOCODING_202603_16"


@lru_cache(maxsize=8)
def get_geocoding_path(lists_dir):
    base = os.path.join(lists_dir, GEOCODING_FILE_BASENAME)
    for candidate in (base + ".csv", base + ".csv.gz"):
        if os.path.exists(candidate):
            return candidate
    raise FileNotFoundError(
        f"Geocoding reference not found: expected {base}.csv or {base}.csv.gz (see common/lists/README.md)."
    )


def open_geocoding_file(lists_dir):
    import gzip

    path = get_geocoding_path(lists_dir)
    if path.endswith(".gz"):
        return gzip.open(path, "rt", newline="")
    return open(path, "r", newline="")


